<body>

    <div class="container">
        <header>
            <h1>Roommate & Family Errand Board</h1>
            <div class="header-actions">
                <button class="btn btn-secondary" onclick="copyRoutePlan()">Copy Current Plan</button>
            </div>
        </header>

        <div class="form-container">
            <form id="errandForm" class="errand-form" onsubmit="addErrand(event)">
                <input type="text" id="stopName" placeholder="Where to? (e.g., Grocery, Target)" required>
                <input type="text" id="assignee" placeholder="Who? (or leave blank)" list="assigneeSuggestions">
                <input type="text" id="category" placeholder="Category (e.g., Food, Kids)" list="categorySuggestions">
                <input type="text" id="notes" placeholder="Notes (e.g., Eggs, return shoes)">
                <button type="submit" class="btn">Add Stop</button>

                <datalist id="assigneeSuggestions"></datalist>
                <datalist id="categorySuggestions"></datalist>
            </form>
        </div>

        <div class="filter-bar">
            <div class="filter-title">🔍 Filters</div>
            <div class="filter-group">
                <label for="filterAssignee">Person:</label>
                <select id="filterAssignee" onchange="applyFilters()">
                    <option value="all">All People</option>
                </select>
            </div>
            <div class="filter-group">
                <label for="filterCategory">Category:</label>
                <select id="filterCategory" onchange="applyFilters()">
                    <option value="all">All Categories</option>
                </select>
            </div>
        </div>

        <div id="errandList" class="errand-list"></div>
        <div id="emptyState" class="empty-state" style="display: none;">No errands found matching your criteria.</div>
    </div>

    <div id="toast" class="toast">Route plan copied to clipboard!</div>

    <script>
        let errands = JSON.parse(localStorage.getItem('roommateErrands')) || [];

        function saveErrands() {
            localStorage.setItem('roommateErrands', JSON.stringify(errands));
            updateFilterOptions();
        }

        function addErrand(e) {
            e.preventDefault();
            const stopName = document.getElementById('stopName').value.trim();
            const assignee = document.getElementById('assignee').value.trim() || 'Unassigned';
            const category = document.getElementById('category').value.trim() || 'General';
            const notes = document.getElementById('notes').value.trim();

            if (!stopName) return;

            errands.push({
                id: Date.now().toString(),
                stopName,
                assignee,
                category,
                notes
            });

            document.getElementById('errandForm').reset();
            saveErrands();
            renderErrands();
        }

        function updateField(id, field, value) {
            const errand = errands.find(e => e.id === id);
            if (errand) {
                let cleanValue = value.trim();
                if (!cleanValue) {
                    if (field === 'assignee') cleanValue = 'Unassigned';
                    if (field === 'category') cleanValue = 'General';
                }
                errand[field] = cleanValue;
                saveErrands();
            }
        }

        function deleteErrand(id) {
            errands = errands.filter(errand => errand.id !== id);
            saveErrands();
            renderErrands();
        }

        function renderErrands() {
            const list = document.getElementById('errandList');
            list.innerHTML = '';

            errands.forEach((errand) => {
                const item = document.createElement('div');
                item.className = 'errand-item';
                item.dataset.id = errand.id;
                item.dataset.assignee = errand.assignee.toLowerCase();
                item.dataset.category = errand.category.toLowerCase();

                item.innerHTML = `
                    <div class="drag-handle" draggable="true">☰</div>
                    <div class="errand-details">
                        <input type="text" class="editable-field stop-name" value="${escapeHtml(errand.stopName)}" placeholder="Stop name" onchange="updateField('${errand.id}', 'stopName', this.value)">
                        <input type="text" class="editable-field assignee" value="${escapeHtml(errand.assignee)}" placeholder="Assignee" onchange="updateField('${errand.id}', 'assignee', this.value); updateFilterOptions();">
                        <input type="text" class="editable-field category" value="${escapeHtml(errand.category)}" placeholder="Category" onchange="updateField('${errand.id}', 'category', this.value); updateFilterOptions();">
                        <input type="text" class="editable-field notes" value="${escapeHtml(errand.notes)}" placeholder="Add notes..." onchange="updateField('${errand.id}', 'notes', this.value)">
                    </div>
                    <div class="actions">
                        <button class="delete-btn" onclick="deleteErrand('${errand.id}')" title="Remove stop">✕</button>
                    </div>
                `;

                setupDragAndDrop(item);
                list.appendChild(item);
            });

            updateFilterOptions();
            applyFilters();
        }

        function setupDragAndDrop(item) {
            const handle = item.querySelector('.drag-handle');

            handle.addEventListener('dragstart', (e) => {
                item.classList.add('dragging');
                e.dataTransfer.setData('text/plain', item.dataset.id);
            });

            handle.addEventListener('dragend', () => {
                item.classList.remove('dragging');
                reorderErrands();
            });
        }

        const listContainer = document.getElementById('errandList');
        listContainer.addEventListener('dragover', e => {
            e.preventDefault();
            const dragging = document.querySelector('.dragging');
            if (!dragging) return;

            const afterElement = getDragAfterElement(listContainer, e.clientY);
            if (afterElement == null) {
                listContainer.appendChild(dragging);
            } else {
                listContainer.insertBefore(dragging, afterElement);
            }
        });

        function getDragAfterElement(container, y) {
            const draggableElements = [...container.querySelectorAll('.errand-item:not(.dragging)')];

            return draggableElements.reduce((closest, child) => {
                const box = child.getBoundingClientRect();
                const offset = y - box.top - box.height / 2;
                if (offset < 0 && offset > closest.offset) {
                    return { offset: offset, element: child };
                } else {
                    return closest;
                }
            }, { offset: -Infinity }).element;
        }

        function reorderErrands() {
            const currentIds = [...listContainer.querySelectorAll('.errand-item')].map(item => item.dataset.id);
            errands = currentIds.map(id => errands.find(errand => errand.id === id));
            localStorage.setItem('roommateErrands', JSON.stringify(errands));
        }

        function updateFilterOptions() {
            const filterAssignee = document.getElementById('filterAssignee');
            const filterCategory = document.getElementById('filterCategory');
            const assigneeDL = document.getElementById('assigneeSuggestions');
            const categoryDL = document.getElementById('categorySuggestions');

            const currentAssigneeFilter = filterAssignee.value;
            const currentCategoryFilter = filterCategory.value;

            // Extract unique values
            const assignees = [...new Set(errands.map(e => e.assignee))].filter(Boolean).sort();
            const categories = [...new Set(errands.map(e => e.category))].filter(Boolean).sort();

            // Populate form autocompletes
            assigneeDL.innerHTML = assignees.map(a => `<option value="${escapeHtml(a)}">`).join('');
            categoryDL.innerHTML = categories.map(c => `<option value="${escapeHtml(c)}">`).join('');

            // Reset filter dropdowns
            filterAssignee.innerHTML = '<option value="all">All People</option>';
            filterCategory.innerHTML = '<option value="all">All Categories</option>';

            assignees.forEach(a => {
                filterAssignee.innerHTML += `<option value="${escapeHtml(a.toLowerCase())}">${escapeHtml(a)}</option>`;
            });
            categories.forEach(c => {
                filterCategory.innerHTML += `<option value="${escapeHtml(c.toLowerCase())}">${escapeHtml(c)}</option>`;
            });

            // Restore previous filter selections if they still exist
            if ([...filterAssignee.options].some(o => o.value === currentAssigneeFilter)) {
                filterAssignee.value = currentAssigneeFilter;
            }
            if ([...filterCategory.options].some(o => o.value === currentCategoryFilter)) {
                filterCategory.value = currentCategoryFilter;
            }
        }

        function applyFilters() {
            const targetAssignee = document.getElementById('filterAssignee').value;
            const targetCategory = document.getElementById('filterCategory').value;
            const items = listContainer.querySelectorAll('.errand-item');
            const emptyState = document.getElementById('emptyState');

            let visibleCount = 0;

            items.forEach(item => {
                const matchesAssignee = (targetAssignee === 'all' || item.dataset.assignee === targetAssignee);
                const matchesCategory = (targetCategory === 'all' || item.dataset.category === targetCategory);

                if (matchesAssignee && matchesCategory) {
                    item.classList.remove('filtered-out');
                    visibleCount++;
                } else {
                    item.classList.add('filtered-out');
                }
            });

            emptyState.style.display = (visibleCount === 0) ? 'block' : 'none';
        }

        function copyRoutePlan() {
            // Only copies visible, filtered stops so people can export specific micro-routes
            const visibleItems = [...listContainer.querySelectorAll('.errand-item:not(.filtered-out)')];

            if (visibleItems.length === 0) return;

            let planText = `📍 EXPORTED ERRAND PLAN - ${new Date().toLocaleDateString()}\n`;
            planText += `====================================\n\n`;

            visibleItems.forEach((item, index) => {
                const errand = errands.find(e => e.id === item.dataset.id);
                if (!errand) return;

                planText += `${index + 1}. ${errand.stopName.toUpperCase()} [${errand.category}]\n`;
                planText += `   Handled By: ${errand.assignee}\n`;
                if (errand.notes) {
                    planText += `   Notes: ${errand.notes}\n`;
                }
                planText += `\n`;
            });

            navigator.clipboard.writeText(planText).then(() => {
                const toast = document.getElementById('toast');
                toast.classList.add('show');
                setTimeout(() => toast.classList.remove('show'), 2500);
            });
        }

        function escapeHtml(str) {
            if (!str) return '';
            return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
        }

        // Initial render
        renderErrands();
    </script>
</body>
</html>

